Your expense tracker is below. Add an item, pick a category, and the total and category bars update as you go. Set a monthly budget to see how much is left. Entries stay only while this page is open, so note down the total before you close it.

```page
<!DOCTYPE html>
<html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<style>
body{font-family:system-ui,sans-serif;margin:0;padding:16px;background:#f7f7f5;color:#222}
h2{margin:0 0 12px;font-size:18px}
.card{background:#fff;border-radius:10px;padding:12px;margin-bottom:12px;box-shadow:0 1px 3px rgba(0,0,0,.08)}
.row{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:8px}
input,select,button{font:inherit;padding:8px;border:1px solid #ccc;border-radius:8px}
input{flex:1;min-width:90px}
button{background:#2f7d4f;color:#fff;border:0;cursor:pointer}
button.x{background:none;color:#b00;padding:2px 8px}
.big{font-size:24px;font-weight:600}
.muted{color:#666;font-size:13px}
.bar{height:8px;background:#e5e5e0;border-radius:4px;overflow:hidden;margin:3px 0 8px}
.bar>div{height:100%;background:#2f7d4f}
.over{color:#b00}
.item{display:flex;justify-content:space-between;align-items:center;padding:6px 0;border-bottom:1px solid #eee}
</style></head><body>
<h2>Monthly expenses</h2>
<div class="card">
  <div class="row">
    <input id="desc" placeholder="What was it?">
    <input id="amt" type="number" min="0" placeholder="Amount (₹)">
  </div>
  <div class="row">
    <select id="cat">
      <option>Food</option><option>Rent</option><option>Travel</option>
      <option>Bills</option><option>Shopping</option><option>Other</option>
    </select>
    <button id="add">Add</button>
  </div>
</div>
<div class="card">
  <div class="muted">Spent this month</div>
  <div class="big" id="total">₹0</div>
  <div class="row" style="margin-top:8px">
    <input id="budget" type="number" min="0" placeholder="Monthly budget (₹)">
  </div>
  <div class="muted" id="left"></div>
</div>
<div class="card"><div class="muted" style="margin-bottom:6px">By category</div><div id="cats"></div></div>
<div class="card"><div class="muted">Entries</div><div id="list"></div></div>
<script>
var items=[];
var fmt=function(n){return '₹'+Number(n).toLocaleString('en-IN')};
function render(){
  var total=0,by={};
  items.forEach(function(i){total+=i.amt;by[i.cat]=(by[i.cat]||0)+i.amt});
  document.getElementById('total').textContent=fmt(total);
  var b=parseFloat(document.getElementById('budget').value)||0;
  var l=document.getElementById('left');
  if(b>0){
    var d=b-total;
    l.textContent=d>=0?fmt(d)+' left of '+fmt(b):fmt(-d)+' over '+fmt(b);
    l.className=d>=0?'muted':'muted over';
  }else{l.textContent='';}
  var c=document.getElementById('cats');c.innerHTML='';
  Object.keys(by).sort(function(a,b){return by[b]-by[a]}).forEach(function(k){
    var w=document.createElement('div');
    var t=document.createElement('div');t.textContent=k+': '+fmt(by[k]);
    var bar=document.createElement('div');bar.className='bar';
    var f=document.createElement('div');f.style.width=(total?by[k]/total*100:0)+'%';
    bar.appendChild(f);w.appendChild(t);w.appendChild(bar);c.appendChild(w);
  });
  var list=document.getElementById('list');list.innerHTML='';
  if(!items.length){list.textContent='Nothing added yet.';list.className='muted';}
  else{list.className='';}
  items.forEach(function(i,idx){
    var r=document.createElement('div');r.className='item';
    var s=document.createElement('span');s.textContent=i.desc+' ('+i.cat+') · '+fmt(i.amt);
    var x=document.createElement('button');x.className='x';x.textContent='✕';
    x.onclick=function(){items.splice(idx,1);render()};
    r.appendChild(s);r.appendChild(x);list.appendChild(r);
  });
}
document.getElementById('add').onclick=function(){
  var a=parseFloat(document.getElementById('amt').value);
  if(!(a>0))return;
  var d=document.getElementById('desc').value.trim()||'Expense';
  items.unshift({desc:d,amt:a,cat:document.getElementById('cat').value});
  document.getElementById('desc').value='';document.getElementById('amt').value='';
  render();
};
document.getElementById('budget').oninput=render;
render();
</script></body></html>
```
